def _page(name: str, synopsis: str, description: str, details: str, examples: str) -> str:
    return (
        f"NAME\n    {name}\n\n"
        f"SYNOPSIS\n    {synopsis}\n\n"
        f"DESCRIPTION\n    {description}\n\n"
        f"OPTIONS AND ARGUMENTS\n{details}\n\n"
        "EXIT STATUS\n"
        "    0 success; 20 refusal; 31 intentional silence; 32 no result;\n"
        "    33 malformed evidence; 34 orchestration deadline; 35 degraded;\n"
        "    36 sandbox write refused.\n"
        "    The artifact process status is authoritative.\n\n"
        f"EXAMPLES\n{examples}\n"
    )


