HELP: Dict[str, str] = {
    topic: register("help.root" if not topic else "help." + topic.replace(" ", "."), text, "CLI help")
    for topic, text in _RAW.items()
}


def name_line_description(topic: str) -> str:
    """The approved one-line description from a topic's NAME line, for derived surfaces."""
    page = _RAW.get(topic)
    if page is None:
        raise KeyError(f"no help page for topic {topic!r}")
    name_line = page.splitlines()[1].strip()
    prefix, separator, description = name_line.partition(" - ")
    if not separator or not description:
        raise ValueError(f"help NAME line for {topic!r} carries no description")
    return description


def help_for(arguments: Sequence[str]) -> Optional[str]:
    if "--help" not in arguments:
        return None
    if not arguments or arguments[0] == "--help":
        topic = ""
    elif arguments[0] == "overlap" and len(arguments) > 1 and arguments[1] == "report":
        topic = "overlap report"
    elif arguments[0] == "work" and len(arguments) > 1 and arguments[1] in {"add", "claim", "complete", "show"}:
        topic = "work " + arguments[1]
    elif arguments[0] == "intake" and len(arguments) > 1 and arguments[1] == "scan":
        topic = "intake scan"
    elif arguments[0] == "intake" and len(arguments) > 1 and arguments[1] == "show":
        topic = "intake show"
    elif arguments[0] == "intake" and len(arguments) > 1 and arguments[1] in {"adopt", "preview", "dispatch"}:
        topic = "intake " + arguments[1]
    elif arguments[0] == "worker" and len(arguments) > 1 and arguments[1] == "run":
        topic = "worker run"
    elif arguments[0] == "sequencer" and len(arguments) > 1 and arguments[1] in {"status", "serve", "direct"}:
        topic = "sequencer " + arguments[1]
    elif arguments[0] == "journal" and len(arguments) > 1 and arguments[1] in {"checkpoint", "verify"}:
        topic = "journal " + arguments[1]
    elif arguments[0] == "signature" and len(arguments) > 1 and arguments[1] in {"sign", "verify"}:
        topic = "signature " + arguments[1]
    elif arguments[0] == "repair" and len(arguments) > 1 and arguments[1] == "quarantine":
        topic = "repair quarantine"
    elif arguments[0] == "mcp" and len(arguments) > 1 and arguments[1] == "serve":
        topic = "mcp serve"
    elif arguments[0] == "effect" and len(arguments) > 1 and arguments[1] in {"show", "reconcile", "compensate"}:
        topic = "effect " + arguments[1]
    elif arguments[0] == "grant" and len(arguments) > 1 and arguments[1] == "revoke":
        topic = "grant revoke"
    elif arguments[0] == "thread" and len(arguments) > 1 and arguments[1] in {"attach", "observe", "detach", "show"}:
        topic = "thread " + arguments[1]
    elif arguments[0] == "node" and len(arguments) > 1 and arguments[1] in {"add", "spawn", "retire", "switch", "role", "boot", "teardown", "explain", "state-flush"}:
        topic = "node " + arguments[1]
    elif arguments[0] == "role" and len(arguments) > 1 and arguments[1] in {"list", "show"}:
        topic = "role " + arguments[1]
    elif arguments[0] == "quota" and len(arguments) > 1 and arguments[1] in {"collect", "show"}:
        topic = "quota " + arguments[1]
    elif arguments[0] == "context" and len(arguments) > 1:
        if arguments[1] in {"status", "turnover"}:
            topic = "context " + arguments[1]
        elif arguments[1] == "policy":
            if len(arguments) > 2 and arguments[2] in {"set", "show", "clear"}:
                topic = "context policy " + arguments[2]
            else:
                topic = "context policy"
        elif arguments[1] == "reading":
            if len(arguments) > 2 and arguments[2] == "record":
                topic = "context reading record"
            else:
                topic = "context reading"
        else:
            topic = "context"
    elif arguments[0] == "epoch" and len(arguments) > 1 and arguments[1] == "roll":
        topic = "epoch roll"
    elif arguments[0] == "wake" and len(arguments) > 1 and arguments[1] == "daemon":
        if len(arguments) > 2 and arguments[2] in {"consent", "bind", "install", "start", "status", "stop", "remove", "revoke"}:
            topic = "wake daemon " + arguments[2]
        else:
            topic = "wake daemon"
    elif arguments[0] == "wake" and len(arguments) > 1 and arguments[1] in {"arm", "pause", "resume", "status"}:
        topic = "wake " + arguments[1]
    elif arguments[0] == "update" and len(arguments) > 1 and arguments[1] == "fleet":
        if len(arguments) > 2 and arguments[2] in {"preview", "apply"}:
            topic = "update fleet " + arguments[2]
        else:
            topic = "update fleet"
    elif arguments[0] == "confluence" and len(arguments) > 1 and arguments[1] in {"grant", "revoke", "status", "bundle", "adopt", "release"}:
        topic = "confluence " + arguments[1]
    elif arguments[0] == "presence" and len(arguments) > 1 and arguments[1] in {"report", "show"}:
        topic = "presence " + arguments[1]
    else:
        topic = arguments[0]
    return HELP.get(topic)
